Task<int> ReadAsync(byte[] buf, int off, int n) {
    var tcs = new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously);
    BeginRead(buf, off, n, iar => {
        try { tcs.TrySetResult(EndRead(iar)); }        // resolve exactly once
        catch (Exception ex) { tcs.TrySetException(ex); }
    }, null);
    return tcs.Task;                                   // the handle given to callers
}

